/* StayQuest — Shared Styles */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --navy: #003B95;
  --blue: #006CE4;
  --gold: #FFB700;
  --gold-hover: #E5A500;
  --bg: #FFFFFF;
  --bg-light: #F5F5F5;
  --bg-section: #FAFAFA;
  --text: #1A1A2E;
  --text-secondary: #555;
  --text-muted: #888;
  --border: #E0E0E0;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 2px 12px rgba(0,0,0,0.08);
  --shadow-lg: 0 8px 30px rgba(0,0,0,0.12);
  --transition: 0.25s ease;
}

html { scroll-behavior: smooth; }
body { font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif; color: var(--text); background: var(--bg); line-height: 1.6; -webkit-font-smoothing: antialiased; }
a { color: var(--blue); text-decoration: none; transition: color var(--transition); }
a:hover { color: var(--navy); }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
input, select { font-family: inherit; }

/* Header */
.site-header { background: var(--navy); color: #fff; position: sticky; top: 0; z-index: 100; }
.header-top { display: flex; align-items: center; justify-content: space-between; max-width: 1200px; margin: 0 auto; padding: 0 24px; height: 64px; }
.logo { font-size: 1.5rem; font-weight: 800; color: #fff; letter-spacing: -0.5px; }
.logo span { color: var(--gold); }
.nav-tabs { display: flex; gap: 0; }
.nav-tabs a { color: rgba(255,255,255,0.75); padding: 20px 16px; font-size: 0.875rem; font-weight: 500; border-bottom: 3px solid transparent; transition: all var(--transition); display: flex; align-items: center; gap: 6px; }
.nav-tabs a:hover { color: #fff; border-bottom-color: rgba(255,255,255,0.4); }
.nav-tabs a.active { color: #fff; border-bottom-color: #fff; }
.header-cta { display: flex; align-items: center; gap: 12px; }
.header-cta a { color: rgba(255,255,255,0.85); font-size: 0.875rem; font-weight: 500; }
.header-cta a:hover { color: #fff; }
.btn-register { background: var(--bg-light); color: var(--navy) !important; padding: 8px 16px; border-radius: var(--radius-sm); font-weight: 600 !important; }
.btn-register:hover { background: #fff; }

/* Hero */
.hero { background: var(--navy); color: #fff; padding: 48px 24px 64px; }
.hero-inner { max-width: 1200px; margin: 0 auto; }
.hero h1 { font-size: 2.5rem; font-weight: 800; margin-bottom: 8px; line-height: 1.2; }
.hero .subtitle { font-size: 1.125rem; opacity: 0.85; margin-bottom: 32px; font-weight: 300; }

/* Search Forms */
.search-form { background: var(--gold); border-radius: var(--radius); padding: 24px; display: flex; flex-wrap: wrap; gap: 12px; align-items: flex-end; }
.search-form .field { flex: 1; min-width: 160px; }
.search-form label { display: block; font-size: 0.75rem; font-weight: 600; color: var(--text); margin-bottom: 4px; text-transform: uppercase; letter-spacing: 0.5px; }
.search-form input, .search-form select { width: 100%; padding: 12px 14px; border: 2px solid var(--border); border-radius: var(--radius-sm); font-size: 0.9375rem; background: #fff; transition: border var(--transition); }
.search-form input:focus, .search-form select:focus { outline: none; border-color: var(--blue); }
.search-form .btn-search { background: var(--navy); color: #fff; border: none; padding: 12px 32px; border-radius: var(--radius-sm); font-size: 1rem; font-weight: 700; transition: background var(--transition); min-width: 120px; }
.search-form .btn-search:hover { background: #002D73; }
.search-form .checkbox-row { width: 100%; display: flex; gap: 24px; margin-top: 8px; }
.search-form .checkbox-row label { font-size: 0.875rem; font-weight: 400; color: var(--text); text-transform: none; letter-spacing: normal; display: flex; align-items: center; gap: 6px; cursor: pointer; }
.search-form .checkbox-row input[type="checkbox"] { width: 18px; height: 18px; accent-color: var(--navy); }
.search-form .radio-row { width: 100%; display: flex; flex-wrap: wrap; gap: 16px; margin-top: 4px; }
.search-form .radio-row label { font-size: 0.875rem; font-weight: 500; color: var(--text); text-transform: none; letter-spacing: normal; display: flex; align-items: center; gap: 6px; cursor: pointer; }
.search-form .radio-row input[type="radio"] { width: 18px; height: 18px; accent-color: var(--navy); }

/* Sections */
.section { max-width: 1200px; margin: 0 auto; padding: 56px 24px; }
.section-alt { background: var(--bg-light); }
.section-alt .section { padding-top: 56px; padding-bottom: 56px; }
.section h2 { font-size: 1.75rem; font-weight: 700; margin-bottom: 8px; }
.section .section-subtitle { color: var(--text-secondary); font-size: 1rem; margin-bottom: 32px; }

/* Trust Badges */
.trust-badges { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
.trust-badge { text-align: center; padding: 24px 16px; }
.trust-badge .badge-icon { width: 56px; height: 56px; margin: 0 auto 16px; background: linear-gradient(135deg, var(--navy), var(--blue)); border-radius: 50%; display: flex; align-items: center; justify-content: center; }
.trust-badge .badge-icon svg { width: 28px; height: 28px; fill: #fff; }
.trust-badge h3 { font-size: 1rem; font-weight: 700; margin-bottom: 4px; color: var(--text); }
.trust-badge p { font-size: 0.8125rem; color: var(--text-secondary); line-height: 1.5; }

/* Cards Grid */
.cards-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 20px; }
.card { background: #fff; border-radius: var(--radius); overflow: hidden; box-shadow: var(--shadow); transition: transform var(--transition), box-shadow var(--transition); }
.card:hover { transform: translateY(-4px); box-shadow: var(--shadow-lg); }
.card-image { height: 180px; background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); position: relative; }
.card-image .placeholder-text { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.6); font-size: 0.875rem; font-weight: 500; }
.card-body { padding: 16px; }
.card-body h3 { font-size: 1rem; font-weight: 600; margin-bottom: 4px; }
.card-body .card-location { font-size: 0.8125rem; color: var(--text-secondary); margin-bottom: 8px; }
.card-body .card-rating { display: flex; align-items: center; gap: 8px; margin-bottom: 8px; }
.card-body .rating-score { background: var(--navy); color: #fff; padding: 4px 8px; border-radius: 6px; font-size: 0.8125rem; font-weight: 700; }
.card-body .rating-label { font-size: 0.8125rem; font-weight: 600; color: var(--text); }
.card-body .rating-count { font-size: 0.75rem; color: var(--text-muted); }
.card-body .card-price { font-size: 1.25rem; font-weight: 800; color: var(--text); }
.card-body .card-price .original { text-decoration: line-through; color: var(--text-muted); font-weight: 400; font-size: 0.9375rem; margin-left: 4px; }
.card-body .card-price .sale { color: #C62828; }
.card-body .card-duration { font-size: 0.8125rem; color: var(--text-secondary); }

/* Property Types */
.property-types { display: flex; flex-wrap: wrap; gap: 12px; }
.property-chip { background: var(--bg-light); border: 1px solid var(--border); border-radius: 999px; padding: 10px 20px; font-size: 0.875rem; font-weight: 500; color: var(--text); cursor: pointer; transition: all var(--transition); }
.property-chip:hover { border-color: var(--blue); color: var(--blue); background: rgba(0,108,228,0.05); }

/* Tabs */
.tab-bar { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; border-bottom: 2px solid var(--border); padding-bottom: 0; }
.tab-btn { background: none; border: none; padding: 10px 16px; font-size: 0.875rem; font-weight: 500; color: var(--text-secondary); cursor: pointer; border-bottom: 3px solid transparent; margin-bottom: -2px; transition: all var(--transition); white-space: nowrap; }
.tab-btn:hover { color: var(--navy); }
.tab-btn.active { color: var(--navy); border-bottom-color: var(--navy); font-weight: 600; }
.tab-panel { display: none; }
.tab-panel.active { display: block; }

/* Carousel */
.carousel-wrapper { position: relative; }
.carousel-track { display: flex; gap: 20px; overflow-x: auto; scroll-behavior: smooth; padding: 4px 0 16px; scrollbar-width: none; }
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-track .card { min-width: 280px; flex-shrink: 0; }
.carousel-arrow { position: absolute; top: 50%; transform: translateY(-60%); width: 44px; height: 44px; border-radius: 50%; background: #fff; border: 1px solid var(--border); box-shadow: var(--shadow); display: flex; align-items: center; justify-content: center; z-index: 2; transition: all var(--transition); }
.carousel-arrow:hover { background: var(--navy); color: #fff; border-color: var(--navy); }
.carousel-arrow:hover svg { fill: #fff; }
.carousel-arrow svg { width: 20px; height: 20px; fill: var(--text-secondary); transition: fill var(--transition); }
.carousel-arrow.left { left: -12px; }
.carousel-arrow.right { right: -12px; }

/* Destination Grid */
.dest-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 16px; }
.dest-item { background: #fff; border-radius: var(--radius-sm); overflow: hidden; box-shadow: 0 1px 4px rgba(0,0,0,0.06); transition: all var(--transition); cursor: pointer; }
.dest-item:hover { box-shadow: var(--shadow); transform: translateY(-2px); }
.dest-item-image { height: 120px; background: linear-gradient(135deg, #2196F3, #1565C0); position: relative; }
.dest-item-image .placeholder-text { position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.6); font-size: 0.8125rem; }
.dest-item-body { padding: 12px; }
.dest-item-body h4 { font-size: 0.9375rem; font-weight: 600; }
.dest-item-body p { font-size: 0.8125rem; color: var(--text-secondary); }

/* Offers */
.offers-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; }
.offer-card { border-radius: var(--radius); padding: 32px; color: #fff; position: relative; overflow: hidden; }
.offer-card.getaway { background: linear-gradient(135deg, #003B95 0%, #006CE4 100%); }
.offer-card.credit { background: linear-gradient(135deg, #1A1A2E 0%, #2D2D44 100%); }
.offer-card h3 { font-size: 1.375rem; font-weight: 700; margin-bottom: 12px; line-height: 1.3; }
.offer-card p { font-size: 0.9375rem; opacity: 0.9; margin-bottom: 20px; line-height: 1.6; }
.offer-card .btn-offer { display: inline-block; background: var(--gold); color: var(--text); padding: 10px 24px; border-radius: var(--radius-sm); font-weight: 700; font-size: 0.9375rem; transition: background var(--transition); border: none; }
.offer-card .btn-offer:hover { background: var(--gold-hover); color: var(--text); }

/* Trip Planner */
.trip-destinations { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 16px; }
.trip-dest-item { display: flex; align-items: center; gap: 12px; padding: 12px; background: #fff; border-radius: var(--radius-sm); border: 1px solid var(--border); transition: all var(--transition); cursor: pointer; }
.trip-dest-item:hover { border-color: var(--blue); box-shadow: 0 2px 8px rgba(0,108,228,0.1); }
.trip-dest-image { width: 56px; height: 56px; border-radius: 8px; background: linear-gradient(135deg, #4FC3F7, #0288D1); flex-shrink: 0; display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.5); font-size: 0.625rem; }
.trip-dest-info h4 { font-size: 0.875rem; font-weight: 600; }
.trip-dest-info p { font-size: 0.75rem; color: var(--text-muted); }

/* Trending */
.trending-tags { display: flex; flex-wrap: wrap; gap: 12px; }
.trending-tag { background: var(--bg-light); border: 1px solid var(--border); border-radius: var(--radius-sm); padding: 12px 24px; font-size: 1rem; font-weight: 600; color: var(--text); transition: all var(--transition); cursor: pointer; }
.trending-tag:hover { border-color: var(--blue); color: var(--blue); }

/* Loyalty CTA */
.loyalty-cta { background: linear-gradient(135deg, var(--navy) 0%, var(--blue) 100%); border-radius: var(--radius); padding: 48px; color: #fff; text-align: center; }
.loyalty-cta h2 { font-size: 2rem; font-weight: 800; margin-bottom: 8px; }
.loyalty-cta .loyalty-sub { font-size: 1.125rem; opacity: 0.9; margin-bottom: 8px; }
.loyalty-cta .loyalty-body { font-size: 1rem; opacity: 0.8; margin-bottom: 24px; max-width: 500px; margin-left: auto; margin-right: auto; }
.loyalty-cta .btn-group { display: flex; gap: 12px; justify-content: center; }
.loyalty-cta .btn-signin { background: #fff; color: var(--navy); padding: 12px 32px; border-radius: var(--radius-sm); font-weight: 700; border: none; font-size: 1rem; transition: background var(--transition); }
.loyalty-cta .btn-signin:hover { background: var(--bg-light); }
.loyalty-cta .btn-register { background: transparent; color: #fff; padding: 12px 32px; border-radius: var(--radius-sm); font-weight: 700; border: 2px solid rgba(255,255,255,0.5); font-size: 1rem; transition: all var(--transition); }
.loyalty-cta .btn-register:hover { border-color: #fff; background: rgba(255,255,255,0.1); }

/* Popular Links */
.popular-links-list { columns: 2; column-gap: 24px; }
.popular-links-list a { display: block; padding: 6px 0; font-size: 0.9375rem; color: var(--text); border-bottom: 1px solid var(--border); }
.popular-links-list a:hover { color: var(--blue); }

/* FAQ Accordion */
.accordion { max-width: 800px; }
.accordion-item { border: 1px solid var(--border); border-radius: var(--radius-sm); margin-bottom: 8px; overflow: hidden; }
.accordion-header { width: 100%; background: #fff; border: none; padding: 16px 20px; font-size: 0.9375rem; font-weight: 600; color: var(--text); text-align: left; display: flex; justify-content: space-between; align-items: center; cursor: pointer; transition: background var(--transition); }
.accordion-header:hover { background: var(--bg-light); }
.accordion-header .arrow { transition: transform var(--transition); font-size: 0.75rem; }
.accordion-item.open .accordion-header { background: var(--bg-light); }
.accordion-item.open .accordion-header .arrow { transform: rotate(180deg); }
.accordion-body { max-height: 0; overflow: hidden; transition: max-height 0.3s ease; }
.accordion-body-inner { padding: 0 20px 16px; font-size: 0.9375rem; color: var(--text-secondary); line-height: 1.7; }

/* Rental Companies */
.rental-logos { display: flex; flex-wrap: wrap; gap: 20px; justify-content: center; align-items: center; }
.rental-logo { width: 120px; height: 60px; background: var(--bg-light); border: 1px solid var(--border); border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 0.875rem; color: var(--text-secondary); transition: all var(--transition); }
.rental-logo:hover { border-color: var(--blue); box-shadow: var(--shadow); }

/* Credit Card Promo */
.credit-promo { background: linear-gradient(135deg, #1A1A2E, #2D2D44); border-radius: var(--radius); padding: 40px; color: #fff; display: flex; align-items: center; justify-content: space-between; gap: 32px; }
.credit-promo h3 { font-size: 1.5rem; font-weight: 700; margin-bottom: 8px; }
.credit-promo p { opacity: 0.85; font-size: 0.9375rem; }
.credit-promo .btn-learn { background: var(--gold); color: var(--text); padding: 12px 24px; border-radius: var(--radius-sm); font-weight: 700; border: none; font-size: 0.9375rem; white-space: nowrap; transition: background var(--transition); }
.credit-promo .btn-learn:hover { background: var(--gold-hover); }

/* Account CTA */
.account-cta { background: var(--bg-light); border-radius: var(--radius); padding: 40px; text-align: center; }
.account-cta h3 { font-size: 1.375rem; font-weight: 700; margin-bottom: 4px; }
.account-cta .cta-sub { color: var(--text-secondary); font-size: 1rem; margin-bottom: 8px; }
.account-cta .cta-body { color: var(--text-muted); font-size: 0.9375rem; margin-bottom: 20px; }
.account-cta .btn-group { display: flex; gap: 12px; justify-content: center; }
.account-cta .btn-primary { background: var(--navy); color: #fff; padding: 10px 24px; border-radius: var(--radius-sm); font-weight: 700; border: none; transition: background var(--transition); }
.account-cta .btn-primary:hover { background: #002D73; }
.account-cta .btn-outline { background: #fff; color: var(--navy); padding: 10px 24px; border-radius: var(--radius-sm); font-weight: 700; border: 2px solid var(--navy); transition: all var(--transition); }
.account-cta .btn-outline:hover { background: var(--navy); color: #fff; }

/* Footer */
.site-footer { background: #1A1A2E; color: rgba(255,255,255,0.7); padding: 56px 24px 32px; }
.footer-inner { max-width: 1200px; margin: 0 auto; }
.footer-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 32px; margin-bottom: 40px; }
.footer-col h4 { color: #fff; font-size: 0.875rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 16px; }
.footer-col a { display: block; font-size: 0.8125rem; color: rgba(255,255,255,0.6); padding: 4px 0; transition: color var(--transition); }
.footer-col a:hover { color: #fff; }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.1); padding-top: 24px; text-align: center; font-size: 0.8125rem; color: rgba(255,255,255,0.4); }

/* Attraction Cards */
.attraction-card { display: flex; align-items: center; gap: 16px; padding: 16px; background: #fff; border-radius: var(--radius-sm); border: 1px solid var(--border); margin-bottom: 12px; transition: all var(--transition); cursor: pointer; }
.attraction-card:hover { border-color: var(--blue); box-shadow: var(--shadow); }
.attraction-card .attr-image { width: 80px; height: 80px; border-radius: var(--radius-sm); background: linear-gradient(135deg, #66BB6A, #2E7D32); flex-shrink: 0; display: flex; align-items: center; justify-content: center; color: rgba(255,255,255,0.5); font-size: 0.625rem; }
.attraction-card .attr-info h4 { font-size: 0.9375rem; font-weight: 600; margin-bottom: 4px; }
.attraction-card .attr-info p { font-size: 0.8125rem; color: var(--text-secondary); }

/* Things to Do Links */
.things-links { columns: 2; column-gap: 24px; }
.things-links a { display: block; padding: 8px 0; font-size: 0.9375rem; border-bottom: 1px solid var(--border); color: var(--text); }
.things-links a:hover { color: var(--blue); }

/* Responsive */
@media (max-width: 1024px) {
  .trust-badges { grid-template-columns: repeat(2, 1fr); }
  .offers-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .credit-promo { flex-direction: column; text-align: center; }
}
@media (max-width: 768px) {
  .header-top { flex-wrap: wrap; height: auto; padding: 12px 16px; gap: 8px; }
  .nav-tabs { order: 3; width: 100%; overflow-x: auto; padding-bottom: 0; }
  .nav-tabs a { padding: 12px 12px; font-size: 0.8125rem; white-space: nowrap; }
  .hero h1 { font-size: 1.75rem; }
  .search-form { flex-direction: column; }
  .search-form .field { min-width: 100%; }
  .trust-badges { grid-template-columns: 1fr 1fr; }
  .dest-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .popular-links-list { columns: 1; }
  .things-links { columns: 1; }
  .loyalty-cta { padding: 32px 20px; }
  .loyalty-cta h2 { font-size: 1.5rem; }
  .section h2 { font-size: 1.375rem; }
  .tab-bar { overflow-x: auto; flex-wrap: nowrap; }
  .trip-destinations { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 480px) {
  .trust-badges { grid-template-columns: 1fr; }
  .dest-grid { grid-template-columns: 1fr; }
  .trip-destinations { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .offers-grid { grid-template-columns: 1fr; }
  .cards-grid { grid-template-columns: 1fr; }
}
